-- One-time: the PENTA-CUT brand (Solutions, Groove-Turn) with its uses: the
-- PENTA insert families on the ISCAR intranet e-catalog (families with the
-- same description share a use), each linked to its family page. An existing
-- PENTA-CUT (also spelled PENTACUT) is kept: it gets the application, a
-- description if it has none, and the uses it doesn't have (by name).
INSERT INTO "Innovation" ("id", "name", "category", "description")
SELECT 'innovation_penta_cut', 'PENTA-CUT', 'Grooving & parting', $u$Pentagonal inserts with 5 cutting edges for grooving, parting, recessing, face grooving and external threading.$u$
WHERE NOT EXISTS (SELECT 1 FROM "Innovation" WHERE upper(replace(replace("name", '-', ''), ' ', '')) = 'PENTACUT')
ON CONFLICT DO NOTHING;

UPDATE "Innovation" SET "description" = $u$Pentagonal inserts with 5 cutting edges for grooving, parting, recessing, face grooving and external threading.$u$
WHERE upper(replace(replace("name", '-', ''), ' ', '')) = 'PENTACUT' AND ("description" IS NULL OR trim("description") = '');

INSERT INTO "_ApplicationToInnovation" ("A", "B")
SELECT a."id", i."id"
FROM "Application" a, "Innovation" i
WHERE lower(replace(a."name", ' ', '-')) = 'groove-turn' AND upper(replace(replace(i."name", '-', ''), ' ', '')) = 'PENTACUT'
ON CONFLICT DO NOTHING;

